<script>
(()=>{const t=document.querySelector('meta[name="csrf-token"]')?.content,c=d=>d?new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(d)):'--',g=()=>new Promise(r=>!navigator.geolocation?r({}):navigator.geolocation.getCurrentPosition(p=>r({latitude:p.coords.latitude,longitude:p.coords.longitude}),()=>r({}),{enableHighAccuracy:true,timeout:7000,maximumAge:0})),u=p=>{document.getElementById('attStatus').textContent=p?.record?.status_label||'Not Punched';document.getElementById('attIn').textContent=c(p?.record?.first_punch_in_at);document.getElementById('attOut').textContent=c(p?.record?.last_punch_out_at);document.getElementById('attMsg').textContent=p?.record?.info_line||'Attendance updated.';document.getElementById('attInBtn').disabled=!!p?.record?.first_punch_in_at;document.getElementById('attOutBtn').disabled=!p?.record?.first_punch_in_at||!!p?.record?.last_punch_out_at},h=async e=>{const l=await g(),r=await fetch(e,{method:'POST',headers:{'X-CSRF-TOKEN':t,Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify({...l,source:'ad_manager_dashboard'})}),j=await r.json().catch(()=>({}));if(!r.ok||!j.success)throw new Error(j.message||'Attendance request failed.');u({record:j.data})};document.getElementById('attInBtn')?.addEventListener('click',()=>h('/api/attendance/punch-in'));document.getElementById('attOutBtn')?.addEventListener('click',()=>h('/api/attendance/punch-out'));})();
</script>

